  ground = world.add(new Body(40, -1.2, 160, 2.4, 0, {
    kind: "ground", layer: -1, mu: GROUND_MU, e: 0.05,
  }));

  car = world.add(new Body(carStartX, CAR_H * 0.5, CAR_W, CAR_H, CAR_MASS, {
    kind: "car", layer: -1, mu: 0.62, e: 0.11,
  }));
