      if (!odd) {
        for (let c = 0; c < cols; c++) {
          const x = x0 + BRICK_W * (c + 0.5);
          const b = world.add(new Body(x, y, BRICK_W, BRICK_H, bm, {
            kind: "brick", layer: L, mu: BRICK_MU, e: BRICK_E, shade: shadeOf(nextId),
          }));
          b.sleep();
          bricks.push(b);
        }
      } else {
        const halfW = BRICK_W * 0.5;
        const halfM = bm * 0.5;
        const left = world.add(new Body(x0 + halfW * 0.5, y, halfW, BRICK_H, halfM, {
          kind: "brick", layer: L, mu: BRICK_MU, e: BRICK_E, shade: shadeOf(nextId), half: true,
        }));
        left.sleep(); bricks.push(left);
        for (let c = 0; c < cols - 1; c++) {
          const x = x0 + halfW + BRICK_W * (c + 0.5);
