            kind: "brick", layer: L, mu: BRICK_MU, e: BRICK_E, shade: shadeOf(nextId),
          }));
          b.sleep();
          bricks.push(b);
        }
        const right = world.add(new Body(x0 + halfW + BRICK_W * (cols - 1) + halfW * 0.5, y, halfW, BRICK_H, halfM, {
          kind: "brick", layer: L, mu: BRICK_MU, e: BRICK_E, shade: shadeOf(nextId), half: true,
        }));
        right.sleep(); bricks.push(right);
      }
    }
  }

  camX = (carStartX + wallLeft) * 0.5 + 1.2;
  camY = Math.max(1.15, wallTop * 0.28);
  phase = launch ? "LAUNCH" : "READY";
  running = !!launch;
  updateStrip();
  setStatus(phase);
}

