+  running = !!launch;
+  status = launch ? "LAUNCH" : "READY";
+  $("wallStat").textContent = bricks.length + " bricks · " + wallMass.toLocaleString(undefined, { maximumFractionDigits: 1 }) + " kg";
+  updateHud();
+}
+
+function updateHud() {
+  const sp = car ? Math.hypot(car.vel.x, car.vel.y, car.vel.z) : 0;
+  $("mSpeed").innerHTML = sp.toFixed(1) + "<em>m/s</em>";
+  $("mTime").innerHTML = time.toFixed(2) + "<em>s</em>";
+  $("mMove").textContent = String(moving);
+  $("mImpact").innerHTML = impactSpeed == null ? "—<em></em>" : impactSpeed.toFixed(1) + "<em>m/s</em>";
+  $("status").textContent = status;
+  $("statusLine").dataset.s = status;
+}
+
+function project(x, y, z) {
+  const sx = (x * VX + z * VZ) * PPM * cam.zoom;
+  const sy = y * PPM * cam.zoom;
+  const shx = Math.sin(time * 78) * shake * 7;
+  const shy = Math.cos(time * 63) * shake * 4;
+  return [cam.ox + sx + shx, cam.oy - sy + shy];
+}
+
+function layoutCamera() {
+  const cols = settings.cols;
+  const rows = settings.rows;
+  const layers = settings.layers;
+  const zHalf = cols * BRICK_W * 0.5 + 0.8;
+  const x0 = -0.3;
+  const x1 = wallFront + layers * BRICK_D + 5.5;
+  const y1 = Math.max(2.6, rows * BRICK_H + 1.15);
+  const corners = [
+    x0 * VX + (-zHalf) * VZ,
+    x0 * VX + zHalf * VZ,
+    x1 * VX + (-zHalf) * VZ,
+    x1 * VX + zHalf * VZ,
+  ];
+  const minS = Math.min(...corners);
+  const maxS = Math.max(...corners);
+  const worldW = maxS - minS;
+  const margin = 26;
+  const zoom = Math.min(1, (viewW - margin * 2) / (worldW * PPM), (viewH - margin * 2) / ((y1 + 0.45) * PPM));
+  cam.zoom = Math.max(0.28, zoom);
+  const mid = (minS + maxS) * 0.5;
+  cam.ox = viewW * 0.5 - mid * PPM * cam.zoom;
+  cam.oy = viewH - 18 - 0.08 * PPM * cam.zoom;
+}
+
+function poly(points, fill, stroke) {
+  ctx.beginPath();
+  ctx.moveTo(points[0][0], points[0][1]);
+  for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
+  ctx.closePath();
+  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
+  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1; ctx.stroke(); }
+}
+
+function drawBox(body, rgb, inset) {
+  const faces = [];
+  for (let f = 0; f < FACES.length; f++) {
+    const face = FACES[f];
+    const n = scale(body.axes[face.axis], face.sign);
+    const light = clamp(dot(n, v3(-0.32, 0.86, 0.38)), 0, 1);
+    const k = 0.42 + light * 0.72;
+    const pts = [];
+    let depth = 0;
+    for (let i = 0; i < 4; i++) {
+      const v = body.verts[face.idx[i]];
+      let x = v.x, y = v.y, z = v.z;
+      if (inset) {
+        x = body.pos.x + (x - body.pos.x) * inset;
+        y = body.pos.y + (y - body.pos.y) * inset;
+        z = body.pos.z + (z - body.pos.z) * inset;
+      }
+      pts.push(project(x, y, z));
+      depth += -x * VZ + z * VX;
+    }
+    faces.push({ pts, depth: depth * 0.25, k, cull: dot(n, v3(-VZ, 0.15, VX)) });
+  }
+  faces.sort((a, b) => a.depth - b.depth);
+  for (let i = 0; i < faces.length; i++) {
+    const f = faces[i];
+    if (f.cull < -0.05) continue;
+    const col = "rgb(" + (rgb[0] * f.k | 0) + "," + (rgb[1] * f.k | 0) + "," + (rgb[2] * f.k | 0) + ")";
+    poly(f.pts, col, "rgba(30,16,12,0.45)");
+  }
+}
+
+function carLocalPoint(lx, ly, side) {
+  let x = lx;
+  if (x > 0.55) x -= crumple * ((x - 0.55) / (CAR_L * 0.5 - 0.55));
+  const c = Math.cos(car.angle), s = Math.sin(car.angle);
+  const rx = x * c - ly * s;
+  const ry = x * s + ly * c;
+  return project(car.pos.x + rx, car.pos.y + ry, side);
+}
+
+const PROFILE = [
+  [-2.08, -0.58], [-2.02, -0.22], [-1.62, -0.16], [-1.22, 0.16], [-0.78, 0.46],
+  [-0.28, 0.64], [0.22, 0.66], [0.62, 0.40], [1.05, 0.10], [1.62, 0.02],
+  [2.06, -0.12], [2.08, -0.40], [1.58, -0.58], [1.12, -0.58], [0.92, -0.30],
+  [0.28, -0.30], [0.06, -0.58], [-0.62, -0.58], [-0.84, -0.30], [-1.58, -0.30], [-1.82, -0.58],
+];
+const GLASS = [[-0.62, 0.22], [-0.22, 0.52], [0.18, 0.54], [0.48, 0.36], [0.42, 0.18], [-0.55, 0.16]];
+
+function drawCar() {
+  const hz = CAR_Z * 0.5;
+  const near = hz;
+  const far = -hz;
+  const depthFar = car.pos.z * 0 + far;
+  const order = depthFar < near ? [far, near] : [near, far];
+  for (let s = 0; s < 2; s++) {
+    const side = order[s];
+    const ring = PROFILE.map(([x, y]) => carLocalPoint(x, y, side));
+    poly(ring, s === 0 ? "#8e2d28" : "#c23b32", "#2a1210");
+    if (s === 1) {
+      poly(GLASS.map(([x, y]) => carLocalPoint(x, y, side)), "#9fd0dc", "#24343a");
+      ctx.beginPath();
+      const a = carLocalPoint(1.92, -0.18, side);
+      const b = carLocalPoint(2.02, -0.34, side);
+      ctx.strokeStyle = "#f2e7c9";
+      ctx.lineWidth = 2;
+      ctx.moveTo(a[0], a[1]);
+      ctx.lineTo(b[0], b[1]);
+      ctx.stroke();
+    }
+  }
+  const bridge = [PROFILE[0], PROFILE[10], PROFILE[11], PROFILE[12]];
+  for (let i = 0; i < PROFILE.length; i++) {
+    const a = PROFILE[i];
+    const b = PROFILE[(i + 1) % PROFILE.length];
+    const quad = [carLocalPoint(a[0], a[1], far), carLocalPoint(b[0], b[1], far), carLocalPoint(b[0], b[1], near), carLocalPoint(a[0], a[1], near)];
+    const midY = (a[1] + b[1]) * 0.5;
+    const col = midY > 0.2 ? "#9a332c" : "#a33a32";
+    poly(quad, col, null);
+  }
+  poly(PROFILE.map(([x, y]) => carLocalPoint(x, y, near)), "#c23b32", "#2a1210");
+  poly(GLASS.map(([x, y]) => carLocalPoint(x, y, near)), "#b7e0ea", "#24343a");
+  drawWheel(AXLE_X, near);
+  drawWheel(-AXLE_X, near);
+  drawWheel(AXLE_X, far * 0.15);
+  drawWheel(-AXLE_X, far * 0.15);
+}
+
+function drawWheel(axle, side) {
+  const ly = -CAR_H * 0.5 + WHEEL_R;
+  const c = Math.cos(car.angle), s = Math.sin(car.angle);
+  const rx = axle * c - ly * s;
+  const ry = axle * s + ly * c;
+  const center = [car.pos.x + rx, car.pos.y + ry];
+  const spin = axle > 0 ? car.wheelW[0] : car.wheelW[1];
+  const pts = [];
+  const rim = [];
+  for (let i = 0; i < 18; i++) {
+    const a = (i / 18) * Math.PI * 2 + spin * 0.05;
+    const lx = axle + Math.cos(a) * WHEEL_R;
+    const yy = ly + Math.sin(a) * WHEEL_R;
+    const px = lx * c - yy * s;
+    const py = lx * s + yy * c;
+    pts.push(project(car.pos.x + px, car.pos.y + py, side));
+    const lx2 = axle + Math.cos(a) * WHEEL_R * 0.42;
+    const yy2 = ly + Math.sin(a) * WHEEL_R * 0.42;
+    const qx = lx2 * c - yy2 * s;
+    const qy = lx2 * s + yy2 * c;
+    rim.push(project(car.pos.x + qx, car.pos.y + qy, side));
+  }
+  poly(pts, "#1b1b1b", "#0a0a0a");
+  poly(rim, "#c8c2b4", null);
+  void center;
+}
+
+function drawWorld() {
+  layoutCamera();
+  const sky = ctx.createLinearGradient(0, 0, 0, viewH);
+  sky.addColorStop(0, "#b7cddb");
+  sky.addColorStop(0.55, "#e4eef3");
+  sky.addColorStop(1, "#d9cbb6");
+  ctx.fillStyle = sky;
+  ctx.fillRect(0, 0, viewW, viewH);
+
+  const zHalf = settings.cols * BRICK_W * 0.5 + 2.4;
+  const x0 = -1.5;
+  const x1 = wallFront + settings.layers * BRICK_D + 14;
+  const g = [
+    project(x0, 0, -zHalf),
+    project(x1, 0, -zHalf),
+    project(x1, 0, zHalf),
+    project(x0, 0, zHalf),
+  ];
+  poly(g, "#5e6562", null);
+  const shoulder = [
+    project(x0, 0, -zHalf - 3.2),
+    project(x1, 0, -zHalf - 3.2),
+    project(x1, 0, -zHalf),
+    project(x0, 0, -zHalf),
+  ];
+  poly(shoulder, "#8d866f", null);
+  const shoulder2 = [
+    project(x0, 0, zHalf),
+    project(x1, 0, zHalf),
+    project(x1, 0, zHalf + 3.2),
+    project(x0, 0, zHalf + 3.2),
+  ];
+  poly(shoulder2, "#8d866f", null);
+
+  ctx.lineWidth = 1;
+  ctx.strokeStyle = "rgba(255,255,255,0.16)";
+  for (let x = 0; x <= x1; x += 1) {
+    ctx.beginPath();
+    const a = project(x, 0.003, -zHalf);
+    const b = project(x, 0.003, zHalf);
+    ctx.moveTo(a[0], a[1]);
+    ctx.lineTo(b[0], b[1]);
+    ctx.stroke();
+  }
+  ctx.strokeStyle = "rgba(230,200,80,0.9)";
+  ctx.setLineDash([8, 10]);
+  ctx.lineWidth = 2;
+  for (const z of [-1.05, 1.05]) {
+    ctx.beginPath();
+    const a = project(0.2, 0.01, z);
+    const b = project(wallFront - 0.15, 0.01, z);
+    ctx.moveTo(a[0], a[1]);
+    ctx.lineTo(b[0], b[1]);
+    ctx.stroke();
+  }
+  ctx.setLineDash([]);
+  ctx.strokeStyle = "#e8d56a";
+  ctx.lineWidth = 3;
+  ctx.beginPath();
+  const wa = project(wallFront, 0.012, -settings.cols * BRICK_W * 0.5);
+  const wb = project(wallFront, 0.012, settings.cols * BRICK_W * 0.5);
+  ctx.moveTo(wa[0], wa[1]);
+  ctx.lineTo(wb[0], wb[1]);
+  ctx.stroke();
+
+  ctx.fillStyle = "#f4f1e6";
+  ctx.font = "12px ui-monospace, Menlo, monospace";
+  for (let x = 0; x <= 16; x += 2) {
+    const p = project(x, 0.02, zHalf + 0.15);
+    ctx.fillText(x + " m", p[0] - 8, p[1] + 14);
+  }
+
+  for (let i = 0; i < skids.length; i++) {
+    const s = skids[i];
+    const p = project(s.x, 0.02, s.z);
+    ctx.fillStyle = "rgba(20,20,20,0.45)";
+    ctx.fillRect(p[0], p[1], 3, 2);
+  }
+
+  const drawables = [];
+  for (let i = 0; i < bricks.length; i++) {
+    const b = bricks[i];
+    drawables.push({ depth: -b.pos.x * VZ + b.pos.z * VX, kind: "brick", b });
+  }
+  drawables.push({ depth: -car.pos.x * VZ + car.pos.z * VX, kind: "car" });
+  for (let i = 0; i < dust.length; i++) {
+    const p = dust[i];
+    drawables.push({ depth: -p.x * VZ + p.z * VX, kind: "dust", p });
+  }
+  drawables.sort((a, b) => a.depth - b.depth);
+  for (let i = 0; i < drawables.length; i++) {
+    const d = drawables[i];
+    if (d.kind === "brick") drawBox(d.b, d.b.rgb, 0.985);
+    else if (d.kind === "car") drawCar();
+    else {
+      const p = project(d.p.x, d.p.y, d.p.z);
+      ctx.fillStyle = "rgba(90,78,68," + (d.p.life * 0.55).toFixed(3) + ")";
+      const rad = d.p.r * PPM * cam.zoom * (1.4 - d.p.life);
+      ctx.beginPath();
+      ctx.arc(p[0], p[1], Math.max(1, rad), 0, Math.PI * 2);
+      ctx.fill();
+    }
+  }
+
+  const bar = PPM * cam.zoom;
+  ctx.fillStyle = "#172018";
+  ctx.fillRect(16, viewH - 28, bar, 4);
+  ctx.font = "12px ui-monospace, Menlo, monospace";
+  ctx.fillText("1 m", 16, viewH - 34);
+}
+
+function drawTrace() {
+  const w = trace.clientWidth || 300;
+  const h = trace.clientHeight || 72;
+  const ratio = Math.min(2, dpr);
+  if (trace.width !== Math.floor(w * ratio) || trace.height !== Math.floor(h * ratio)) {
+    trace.width = Math.floor(w * ratio);
+    trace.height = Math.floor(h * ratio);
+  }
+  tctx.setTransform(ratio, 0, 0, ratio, 0, 0);
+  tctx.clearRect(0, 0, w, h);
+  tctx.fillStyle = "#171910";
+  tctx.fillRect(0, 0, w, h);
+  tctx.strokeStyle = "#34382c";
+  tctx.strokeRect(0.5, 0.5, w - 1, h - 1);
+  const maxV = Math.max(45, settings.speed);
+  tctx.strokeStyle = "#ef5d2c";
+  tctx.lineWidth = 1.6;
+  tctx.beginPath();
+  if (samples.length === 0) {
+    tctx.moveTo(0, h - 8);
+    tctx.lineTo(w, h - 8);
+  }
+  for (let i = 0; i < samples.length; i++) {
+    const x = (i / 239) * (w - 8) + 4;
+    const y = h - 6 - (samples[i] / maxV) * (h - 14);
+    if (i === 0) tctx.moveTo(x, y);
+    else tctx.lineTo(x, y);
+  }
+  tctx.stroke();
+  tctx.fillStyle = "#8d927f";
+  tctx.font = "11px ui-monospace, Menlo, monospace";
+  tctx.fillText("speed", 8, 14);
+}
+
+function frame(t) {
+  if (!lastT) lastT = t;
+  let dt = (t - lastT) / 1000;
+  lastT = t;
+  if (dt > 0.05) dt = 0.05;
+  if (running) {
+    acc += dt;
+    let guard = 0;
+    while (acc >= STEP && guard < 6) {
+      physicsStep();
+      acc -= STEP;
+      guard++;
+    }
+  }
+  resize();
+  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
+  drawWorld();
+  drawTrace();
+  updateHud();
+  requestAnimationFrame(frame);
+}
+
+function resize() {
+  const rect = view.parentElement.getBoundingClientRect();
+  dpr = Math.min(2, window.devicePixelRatio || 1);
+  viewW = Math.max(1, rect.width);
+  viewH = Math.max(1, rect.height);
+  const w = Math.round(viewW * dpr);
+  const h = Math.round(viewH * dpr);
+  if (view.width !== w || view.height !== h) {
+    view.width = w;
+    view.height = h;
+  }
+}
+
+function onSetting() {
+  readSettings();
+  if (running) {
+    pending = true;
+    $("pending").textContent = "Applies on the next test.";
+    $("wallStat").textContent = "next wall " + (settings.cols * settings.rows * settings.layers) + " · " + (settings.cols * settings.rows * settings.layers * settings.mass).toFixed(1) + " kg";
+    return;
+  }
+  buildScene(false);
+}
+
+$("test").addEventListener("click", () => buildScene(true));
+$("reset").addEventListener("click", () => buildScene(false));
+for (const id of ["sSpeed", "sCols", "sRows", "sLayers", "sMass"]) {
+  $(id).addEventListener("input", onSetting);
+}
+window.addEventListener("keydown", (e) => {
+  if (e.code === "Space" && e.target.tagName !== "INPUT") {
+    e.preventDefault();
+    buildScene(true);
+  }
+});
+window.addEventListener("resize", resize);
+window.addEventListener("error", (e) => {
+  status = "ERROR";
+  $("status").textContent = e.message;
+});
+
+buildScene(false);
+resize();
+requestAnimationFrame(frame);
+
+window.__probe = () => {
+  let maxPen = 0;
+  let minY = Infinity;
+  let maxAbsVy = 0;
+  for (let i = 0; i < bricks.length; i++) {
+    const b = bricks[i];
+    minY = Math.min(minY, b.aabb.minY);
+    maxAbsVy = Math.max(maxAbsVy, Math.abs(b.vel.y));
+    if (b.aabb.minY < -maxPen) maxPen = -b.aabb.minY;
+  }
+  return {
+    status,
+    time,
+    speed: car ? Math.hypot(car.vel.x, car.vel.y) : 0,
+    vx: car ? car.vel.x : 0,
+    carX: car ? car.pos.x : 0,
+    carY: car ? car.pos.y : 0,
+    angle: car ? car.angle : 0,
+    moving,
+    impactSpeed,
+    bricks: bricks.length,
+    wallMass,
+    minY,
+    maxPen,
+    maxAbsVy,
+    dust: dust.length,
+    settings: { ...settings },
+  };
+};
+</script>
+</body>
+</html>

