function tangentsOf(n) {
  const hint = Math.abs(n.y) < 0.85 ? v3(0, 1, 0) : v3(1, 0, 0);
  let t1 = cross(n, hint);
  const L = len(t1) || 1;
  t1 = v3(t1.x / L, t1.y / L, t1.z / L);
  const t2 = cross(n, t1);
  return [t1, t2];
}

function solveVelocity(contacts) {
  for (let i = 0; i < contacts.length; i++) {
    const c = contacts[i];
    if (c.nImp === 0 && c.t1Imp === 0 && c.t2Imp === 0) continue;
    applyImpulse(c.A, scale(c.n, -c.nImp), c.rA);
    applyImpulse(c.B, scale(c.n, c.nImp), c.rB);
  }
  for (let iter = 0; iter < 14; iter++) {
    for (let i = 0; i < contacts.length; i++) {
      const c = contacts[i];
      const va = velAt(c.A, c.rA);
      const vb = velAt(c.B, c.rB);
      const rvx = vb.x - va.x, rvy = vb.y - va.y, rvz = vb.z - va.z;
      const vn = rvx * c.n.x + rvy * c.n.y + rvz * c.n.z;
      const e = vn < -REST_V ? c.e : 0;
      const denom = response(c.A, c.n, c.rA) + response(c.B, c.n, c.rB);
      if (denom < 1e-8) continue;
      let j = (-(1 + e) * vn) / denom;
      const old = c.nImp;
      c.nImp = Math.max(0, old + j);
      j = c.nImp - old;
      if (j !== 0) {
        applyImpulse(c.A, scale(c.n, -j), c.rA);
        applyImpulse(c.B, scale(c.n, j), c.rB);
        if (c.A.isCar || c.B.isCar) {
          const mag = Math.abs(j);
          if (mag > 40 && (c.A !== GROUND && c.B !== GROUND)) {
            shake = Math.min(1, shake + mag * 0.00002);
            crumple = Math.min(0.42, crumple + mag * 0.0000045);
            if (dust.length < 220 && mag > 80) spawnDust(c.p, c.n, mag);
          }
        }
      }
      if (c.wheel >= 0) {
        solveWheel(c);
        continue;
      }
      const [t1, t2] = tangentsOf(c.n);
      solveTangent(c, t1, "t1Imp");
      solveTangent(c, t2, "t2Imp");
    }
  }
  contactCache = new Map();
  for (let i = 0; i < contacts.length; i++) {
    const c = contacts[i];
    let arr = contactCache.get(c.key);
    if (!arr) { arr = []; contactCache.set(c.key, arr); }
    arr.push({ px: c.p.x, py: c.p.y, pz: c.p.z, nImp: c.nImp, t1Imp: c.t1Imp, t2Imp: c.t2Imp });
  }
}

function solveTangent(c, t, field) {
  const va = velAt(c.A, c.rA);
  const vb = velAt(c.B, c.rB);
  const rvx = vb.x - va.x, rvy = vb.y - va.y, rvz = vb.z - va.z;
  const vt = rvx * t.x + rvy * t.y + rvz * t.z;
  const denom = response(c.A, t, c.rA) + response(c.B, t, c.rB);
  if (denom < 1e-8) return;
  const limit = c.mu * c.nImp;
  const old = c[field];
  c[field] = clamp(old + (-vt / denom), -limit, limit);
  const j = c[field] - old;
  if (j === 0) return;
  applyImpulse(c.A, scale(t, -j), c.rA);
  applyImpulse(c.B, scale(t, j), c.rB);
  if (c.B && c.B.isCar && c.A === GROUND && Math.abs(vt) > 3.5 && skids.length < 500) {
    skids.push({ x: c.p.x, z: c.p.z, life: 1 });
  }
}

function solveWheel(c) {
  const r = c.rB;
  const va = velAt(car, r);
  const slip = va.x - car.wheelW[c.wheel] * WHEEL_R;
  const K = response(car, v3(1, 0, 0), r);
  const denom = K + (WHEEL_R * WHEEL_R) / WHEEL_I;
  if (denom < 1e-8) return;
  const limit = c.mu * c.nImp;
  const old = c.t1Imp;
  c.t1Imp = clamp(old + (-slip / denom), -limit, limit);
  const j = c.t1Imp - old;
  if (j !== 0) {
    applyImpulse(car, v3(j, 0, 0), r);
    car.wheelW[c.wheel] += -j * WHEEL_R / WHEEL_I;
  }
  if (Math.abs(slip) > 3.2 && skids.length < 500) skids.push({ x: c.p.x, z: 0, life: 1 });
}

function currentPen(c) {
  if (c.A === GROUND) {
    const p = c.B.isCar && c.wheel >= 0
      ? wheelPoint(c.wheel)
      : null;
    if (p) return -(c.B.pos.y + p.y);
    return projectRadius(c.B, c.n) - dot(sub(c.B.pos, v3(c.p.x, 0, c.p.z)), c.n);
  }
  const dist = dot(sub(c.B.pos, c.A.pos), c.n);
  return projectRadius(c.A, c.n) + projectRadius(c.B, c.n) - dist;
}

function wheelPoint(index) {
  const lx = index === 0 ? AXLE_X : -AXLE_X;
  const ly = -CAR_H * 0.5;
  const co = Math.cos(car.angle), si = Math.sin(car.angle);
  return v3(lx * co - ly * si, lx * si + ly * co, 0);
}

function solvePosition(contacts) {
  for (let iter = 0; iter < 6; iter++) {
    let any = false;
    for (let i = 0; i < contacts.length; i++) {
      const c = contacts[i];
      const pen = currentPen(c);
      if (pen <= SLOP) continue;
      const denom = response(c.A, c.n, c.rA) + response(c.B, c.n, c.rB);
      if (denom < 1e-8) continue;
      const corr = Math.min(pen - SLOP, 0.06) * 0.62;
      const j = corr / denom;
      applyPosition(c.A, scale(c.n, -j), c.rA);
      applyPosition(c.B, scale(c.n, j), c.rB);
      any = true;
    }
    if (!any) break;
    if (car) sync(car);
    for (let i = 0; i < bricks.length; i++) if (!bricks[i].asleep) sync(bricks[i]);
  }
}

function spawnDust(p, n, mag) {
  const count = mag > 400 ? 3 : 1;
  for (let i = 0; i < count; i++) {
    const a = rng() * Math.PI * 2;
    const sp = 0.6 + rng() * 2.4;
    dust.push({
      x: p.x, y: Math.max(0.05, p.y), z: p.z,
      vx: n.x * (0.4 + rng()) + Math.cos(a) * sp,
      vy: Math.abs(n.y) * 0.5 + 0.8 + rng() * 1.6,
      vz: n.z * 0.4 + Math.sin(a) * sp,
      life: 0.55 + rng() * 0.35,
