  pts.sort((p, q) => p.x - q.x || p.z - q.z || p.y - q.y);
  return pts;
}

function mixMu(a, b) { return Math.sqrt(a * b); }
function mixE(a, b) { return Math.min(a, b); }

let pairList = [];
const grid = new Map();

function buildPairs() {
  grid.clear();
