    if (b.asleep && !b.isCar) continue;
    const a = b.aabb;
    const x0 = Math.floor(a.minX / cell), x1 = Math.floor(a.maxX / cell);
    const y0 = Math.floor(a.minY / cell), y1 = Math.floor(a.maxY / cell);
    const z0 = Math.floor(a.minZ / cell), z1 = Math.floor(a.maxZ / cell);
    for (let ix = x0; ix <= x1; ix++) {
      for (let iy = y0; iy <= y1; iy++) {
        for (let iz = z0; iz <= z1; iz++) {
          const key = ix + "," + iy + "," + iz;
          let bucket = grid.get(key);
          if (!bucket) { bucket = []; grid.set(key, bucket); }
          for (let k = 0; k < bucket.length; k++) {
            const o = bucket[k];
            if (b.asleep && o.asleep) continue;
            const lo = b.id < o.id ? b.id : o.id;
            const hi = b.id < o.id ? o.id : b.id;
            const pk = lo + ":" + hi;
            if (stamp.has(pk)) continue;
            if (!aabbHit(b.aabb, o.aabb, SKIN)) continue;
            stamp.add(pk);
            pairList.push(b.id < o.id ? [b, o] : [o, b]);
