}

function makeContact(A, B, n, pen, p, extra) {
  const rA = A.isGround ? v3(0, 0, 0) : sub(p, A.pos);
  const rB = B.isGround ? v3(0, 0, 0) : sub(p, B.pos);
  const mu = extra && extra.mu != null ? extra.mu : mixMu(A.mu || GROUND_MU, B.mu || GROUND_MU);
  const e = extra && extra.e != null ? extra.e : mixE(A.e || 0.05, B.e || 0.05);
  return {
