const PVB = [0, 0, 0];

function pointVel(body, rx, ry, rz, out) {
  if (!body || body.isGround) { out[0] = 0; out[1] = 0; out[2] = 0; return; }
  if (body.isCar) {
    out[0] = body.vel.x - body.omega.z * ry;
    out[1] = body.vel.y + body.omega.z * rx;
    out[2] = 0;
    return;
  }
  out[0] = body.vel.x + (body.omega.y * rz - body.omega.z * ry);
  out[1] = body.vel.y + (body.omega.z * rx - body.omega.x * rz);
  out[2] = body.vel.z + (body.omega.x * ry - body.omega.y * rx);
}

function solveVelocity(contacts) {
  for (let iter = 0; iter < 8; iter++) {
    for (let i = 0; i < contacts.length; i++) {
      const c = contacts[i];
      const n = c.n;
      pointVel(c.A, c.rA.x, c.rA.y, c.rA.z, PVA);
      pointVel(c.B, c.rB.x, c.rB.y, c.rB.z, PVB);
      const vn = (PVB[0] - PVA[0]) * n.x + (PVB[1] - PVA[1]) * n.y + (PVB[2] - PVA[2]) * n.z;
      const e = vn < -REST_V ? c.e : 0;
      const denom = responseRaw(c.A, n.x, n.y, n.z, c.rA.x, c.rA.y, c.rA.z)
        + responseRaw(c.B, n.x, n.y, n.z, c.rB.x, c.rB.y, c.rB.z);
      if (denom < 1e-8) continue;
      let j = (-(1 + e) * vn) / denom;
      const old = c.nImp;
      c.nImp = Math.max(0, old + j);
      j = c.nImp - old;
      if (j !== 0) {
        applyJ(c.A, -n.x * j, -n.y * j, -n.z * j, c.rA.x, c.rA.y, c.rA.z);
        applyJ(c.B, n.x * j, n.y * j, n.z * j, c.rB.x, c.rB.y, c.rB.z);
      }
      if (c.wheel >= 0) {
        solveWheel(c);
        continue;
      }
      solveTangent(c, 0);

