function generateContacts() {
  buildPairs();
  const contacts = [];
  for (let i = 0; i < pairList.length; i++) {
    const A = pairList[i][0];
    const B = pairList[i][1];
    if (!A.isGround) {
      if (A.asleep && !B.asleep) A.asleep = false;
      if (B.asleep && !A.asleep) B.asleep = false;
    }
    if (A.isGround) {
      const minY = B.aabb.minY;
      if (minY > SKIN) continue;
