        const c = makeContact(GROUND, B, v3(0, 1, 0), -p.y, v3(p.x, p.y, p.z), {
          mu: B.isCar ? GROUND_MU : mixMu(GROUND_MU, B.mu),
          e: B.isCar ? 0.05 : Math.min(0.08, B.e),
          vi: v,
        });
        c.rB.x = p.x - B.pos.x;
        c.rB.y = p.y - B.pos.y;
        c.rB.z = p.z - B.pos.z;
        contacts.push(c);
      }
