    }
    const hit = sat(A, B);
    if (!hit) continue;
    if (!impacted && (A.isCar || B.isCar)) {
      impacted = true;
      impactSpeed = Math.hypot(car.vel.x, car.vel.y, car.vel.z);
      status = "IMPACT";
    }
    const pts = manifold(A, B, hit.n);
