    }
  }
  if (car && !car.asleep) {
    const c = Math.cos(car.angle), s = Math.sin(car.angle);
    for (let w = 0; w < 2; w++) {
      const lx = w === 0 ? AXLE_X : -AXLE_X;
      const ly = -CAR_H * 0.5;
      const rx = lx * c - ly * s;
      const ry = lx * s + ly * c;
      const py = car.pos.y + ry;
      if (py > 0.03) continue;
      const p = v3(car.pos.x + rx, 0, 0);
      contacts.push(makeContact(GROUND, car, v3(0, 1, 0), -py, p, {
